#include <iostream>
#include <cstdlib>
#include <iomanip>

int main() {
    unsigned int seed = 0;
    // Prompt and read seed
    std::cout << "Enter seed: ";
    if (std::cin >> seed) {
        std::srand(seed);
    }

    // Roll a 6-sided die 10 times
    for (unsigned int i = 1; i <= 10; ++i) {
        // Pick a random number from 1 to 6 and output it
        std::cout << std::setw(10) << (1 + (std::rand() % 6));

        // If counter is divisible by 5, begin a new line of output
        if (i % 5 == 0) {
            std::cout << "\n";
        }
    }

    return 0;
}

#include <iostream>
#include <vector>

enum class Status { Continue, Won, Lost };

struct DiePair {
    int die1;
    int die2;
};

int rollDiceFromPair(int die1, int die2) {
    int sum = die1 + die2;
    std::cout << "Player rolled " << die1 << " + " << die2 << " = " << sum << "\n";
    return sum;
}

int main() {
    // Vector of rolls simulating the textbook sample execution in Fig. 5.15 Part 1:
    // Subsequent roll win: (4, 1) -> point 5; (6, 2) -> 8; (2, 1) -> 3; (3, 2) -> 5 (Win)
    std::vector<DiePair> rolls = {
        {4, 1},
        {6, 2},
        {2, 1},
        {3, 2}
    };

    // If input provides pairs, read them; otherwise use default sample sequence
    int d1, d2;
    std::vector<DiePair> inputRolls;
    while (std::cin >> d1 >> d2) {
        inputRolls.push_back({d1, d2});
    }
    if (!inputRolls.empty()) {
        rolls = inputRolls;
    }

    size_t rollIndex = 0;
    auto nextRoll = [&]() -> int {
        if (rollIndex < rolls.size()) {
            int sum = rollDiceFromPair(rolls[rollIndex].die1, rolls[rollIndex].die2);
            ++rollIndex;
            return sum;
        }
        return 7; // Fallback
    };

    int myPoint = 0;
    Status gameStatus = Status::Continue;
    int sum = nextRoll(); // First roll

    switch (sum) {
        case 7:
        case 11:
            gameStatus = Status::Won;
            break;
        case 2:
        case 3:
        case 12:
            gameStatus = Status::Lost;
            break;
        default:
            gameStatus = Status::Continue;
            myPoint = sum;
            std::cout << "Point is " << myPoint << "\n";
            break;
    }

    while (gameStatus == Status::Continue) {
        sum = nextRoll();
        if (sum == myPoint) {
            gameStatus = Status::Won;
        } else if (sum == 7) {
            gameStatus = Status::Lost;
        }
    }

    if (gameStatus == Status::Won) {
        std::cout << "Player wins\n";
    } else {
        std::cout << "Player loses\n";
    }

    return 0;
}
